// HARDENED: Error-handling deserializer with Dead Letter Queue (DLQ)
@KafkaListener(topics = "orders", errorHandler = "dlqErrorHandler")
public void onMessage(ConsumerRecord record) {
    try {
        OrderEvent event = serializer.deserialize(record.value());
        orderService.process(event);
        ack.acknowledge();
    } catch (DeserializationException de) {
        // Route poison pill immediately to DLQ without halting topic partition commit offset
        dlqProducer.send("orders-dead-letter", record.key(), record.value());
        ack.acknowledge();
    }
}
